#include "minecraft/PlayerLoader.h"
#include "minecraft/Nbt.h"
#include <filesystem>
namespace sanbucraft::minecraft { namespace { std::vector<ItemStack> items(const NbtTag* tag) { std::vector<ItemStack> out; if (!tag || !tag->list()) return out; for (const auto& entry : *tag->list()) { ItemStack item; item.id = entry.find("id") ? entry.find("id")->stringOr() : "minecraft:air"; item.count = static_cast<int>(entry.find("Count") ? entry.find("Count")->integerOr() : 0); item.slot = static_cast<int>(entry.find("Slot") ? entry.find("Slot")->integerOr(-1) : -1); if (item.count > 0 && item.id != "minecraft:air") out.push_back(item); } return out; } }
bool PlayerLoader::loadPlayers(const std::string& worldPath, std::vector<Player>& players, std::string& error) { namespace fs = std::filesystem; players.clear(); const fs::path directory = fs::path(worldPath) / "playerdata"; if (!fs::exists(directory)) return true; for (const auto& file : fs::directory_iterator(directory)) { if (!file.is_regular_file() || file.path().extension() != ".dat") continue; NbtTag root; std::string parseError; if (!NbtReader::readFile(file.path().string(), root, parseError)) { error = "Cannot parse player file " + file.path().filename().string() + ": " + parseError; return false; } Player player; player.uuid = file.path().stem().string(); player.dimension = root.find("Dimension") ? root.find("Dimension")->stringOr(player.dimension) : player.dimension; player.health = root.find("Health") ? root.find("Health")->numberOr(20) : 20; player.foodLevel = static_cast<int>(root.find("foodLevel") ? root.find("foodLevel")->integerOr(20) : 20); player.xpLevel = static_cast<int>(root.find("XpLevel") ? root.find("XpLevel")->integerOr() : 0); player.xpProgress = static_cast<float>(root.find("XpP") ? root.find("XpP")->numberOr() : 0); player.selectedSlot = static_cast<int>(root.find("SelectedItemSlot") ? root.find("SelectedItemSlot")->integerOr() : 0); const auto* pos = root.find("Pos"); if (pos && pos->list() && pos->list()->size() == 3) { player.x = (*pos->list())[0].numberOr(); player.y = (*pos->list())[1].numberOr(); player.z = (*pos->list())[2].numberOr(); } player.inventory = items(root.find("Inventory")); player.armor = items(root.find("ArmorItems")); player.enderChest = items(root.find("EnderItems")); players.push_back(std::move(player)); } return true; }
}
